architecture.h4_f:
msg = CBOR{v:1, mawu, reply_to, sent_at}
ct = AES-GCM-256-Encrypt(k, nonce, msg, aad=room_id)
POST /api/rooms/{id}/messages {ciphertext: hex(ct), nonce: hex}

cryptoWire.h1_f:
pt = CBOR{v:1, mawu, yankhani_ku?, thread_id?, zotchulidwa?, sent_at}
ct = AES-GCM-256-Lemberani(kiyi_chipinda, nonce, pt, aad=hex(id_yachipinda))
waya = CBOR{
  v:1,.
  ciphertext: hex(ct), // kutalika kosiyanasiyana
  nambala: hex (12 B),
  sender_pseudo: hex(16 B),
  kutumiza_pa: unix_ms
}

cryptoWire.h5_f:
kunja = CBOR{
  source_node: hex32,
  target_user: int64,
  mkati_ciphertext: mabayiti,
  mkati_nonce: mabayiti,
  kutumiza_pa: unix_ms
}
sig = Ed25519-Sign(source_priv, kunja)
POST /bungwe/kupereka {envelopu: kunja, sig: hex64}

auth.h1_f:
POST /api/authentication/register
  { lolowera, mawu achinsinsi, x25519_key_public, display_name, foni?, imelo?, avatar_emoji }

Yankho 201 Adapangidwa:
  { access_token, refresh_token, user_id, dzina lolowera, ... }

auth.h3_f:
access_token payload:
  { sub: user_id, jti: device_id, typ: "access", exp: now + 15min }
refresh_token payload:
  { sub: user_id, jti: device_id, typ: "refresh", exp: now + 30d }

HS256-yosaina ndi chinsinsi cha node's 64-byte kuchokera ku .env

auth.h4_f:
register_begin(): chovuta = rand(32)
                    options = {rp.id, user.id, pubKeyCredParams, challenge}
                    zosankha zobwerera

register_finish(chitsimikizo):
  Tsimikizani umboni wotsutsa TPM / Muzu Wotetezedwa wa Enclave CA
  sungani { credential_id, public_key, counter: 0}

auth.h7_f:
POST /api/authentication/qr/begin
  → { nonce: 128-bit hex, ttl: 60}
QR payload = { nonce, user_id, seva: "https://node.example" }

POST /api/authentication/qr/verify { nonce }
  → chipangizo chatsopano cholembetsedwa; Ma JWT adabweranso.

rooms.h6_f:
sender_pseudo = HMAC-SHA256(chipinda_pseudo_salt, sender_id)[:16] // 32 hex
ciphertext = AES-GCM-Encrypt(key_key, nonce, CBOR_payload, aad=room_id)

Fulemu yotengera: {mtundu:"m", chipinda, msg:{id, ct, nonce, sender_pseudo, sent_at}}

files.h2_f:
init POST /api/mafayilo/oyambiranso/init {filename, size, chunk_size_hint}
            ← {load_id, chunk_size}
chunk PUT /api/files/resumable/{upload_id}/chunk/{offset} <ct bytes>
            ← 204
malizani POST /api/files/resumable/{upload_id}/finalise {plain_blake3}
            ← 201 {file_id, url}
TTL pa yosamalizidwa: 24 h

files.h4_f:
deny_list = {
  "ntchito / x-dosexec",
  "ntchito / x-sharedlib",
  "ntchito / x-mach-binary",
}
ngati magic.from_buffer(buf[:1024]) mu deny_list: bweretsani 415

presence.h1_f:
kasitomala: pa kiyibodi yoyamba → tumizani {mtundu:"t", tchulani:"yambani"}
         palibenso kutumiza kwa 3 s pokhapokha ngati dziko litasintha
         10 s pambuyo pa kiyibodi yomaliza → tumizani {mtundu:"t", tchulani:"siyani"}
wolandila: auto-stop 10 s pambuyo pa "kuyamba" komaliza ngati palibe "kuyimitsa" komwe kunafika

calls.h1_f:
POST /api/calls/{room_id}/start {vidiyo, audio} → call_id
WS kuwulutsa {mtundu:"c", mtundu:"itani", call_id}
WS kuwulutsa {mtundu:"c", mtundu:"kupereka", sdp}
WS kuwulutsa {mtundu:"c", mtundu:"yankho", sdp}
WS kuwulutsa {mtundu:"c", mtundu:"wosankha", ayezi} × N
POST /api/calls/{call_id}/end

federation.h2_f:
envelopu = {
  source_node: hex32,
  target_user : int64,
  mkati_ciphertext: mabayiti,
  mkati_nonce : mabayiti,
  kutumiza_pa: unix_ms,
}
sig = Ed25519Sign(source_priv, CBOR(envelopu))
POST /federation/perekani {envelopu, sig }

gossip.h3_f:
malonda = {pubkey, endpoint, advertised_at}
sig = Ed25519-Sign(pubkey_priv, CBOR(advertisement))
malipiro amiseche: [..., {ad, sig}, ...]

wolandila: tsimikizirani kuti sig motsutsana ndi ad.pubkey → sungani ngati zili bwino
zowonjezera: PoW ya 2^18 kutsogolera ziro pa {pubkey, endpoint}

stealth.h2_f:
ClientHello bytes = chrome_120_template yokhala ndi {
  mwachisawawa = mwachisawawa,
  seva_name = dzina lathu la alendo (kapena ECH-lokutidwa),
  session_id = id yathu yagawo,
}
JA4 = t13d_xxxx_xxxx_xxxx (yofanana ndi khola lamakono la Chrome)

stealth.h4_f:
DoH: POST https://cloudflare-dns.com/dns-query {name: x.vortexx.sol}
ECH: ClientHello.extensions += encrypted_sni(public_key_from_HTTPS_record)
DGA: domain(t) = base32( SHA256(mbewu ∥ YYYY-MM-DD))[:16] + ".chitsanzo"

push.h4_f:
iOS NSE: didReceive(pempho) {decrypt(request.content.userInfo)}
Android FCM: onMessageReceived(remoteMessage) {decrypt(remoteMessage.data)}
Webusaiti SW: self.addEventListener('push', e => decrypt(e.data))

controller.h2_f:
chida = chizindikiro_chida
input = gwero mtengo, makiyi/release.key
chiwonetsero = {
  mtundu: "0.1.0",
  build_at: unix_ms,
  mafayilo: [{path, sha256, size}, ...]
}
sig = Ed25519-Sign(release_priv, CBOR(manifest))
zotuluka = INTEGRITY.sig.json = {manifest, sign_by: pub_hex, sig: sig_hex}

bots.h1_f:
pangani: POST /api/bots {username, display_name, code}
          → {bot_id, chizindikiro, pubkey}
kuthamanga: mkati (coroutine mkati node)
      OR zakunja (zosankha zazitali /api/bots/{id}/zosintha, token-auth'd)
uthenga: {mawu, siginecha: Ed25519-Sign(bot_priv, canonical_msg)}

bots.h2_f:
pa / kuyamba {
  tulutsani "Mwalandiridwa, {ctx.first_name}"
}
pa / onjezerani <chinthu> {
  state.list = (state.list kapena []) + [ctx.args.item]
  tulutsani "Wowonjezera: {ctx.args.item}"
}

security.h4_f:
canary.txt (tsiku ndi tsiku):
  {tsiku, sig: Ed25519-Sign(release_priv, date)}
wofuna chithandizo amatsimikizira → kulibe kapena kusakhala bwino

